def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    last_me, last_opp = history[-1]
    rounds_left = 100 - n

    def coop_rate(start):
        if start < 0:
            start = 0
        if start >= n:
            return 0.5
        c = 0
        total = 0
        for i in range(start, n):
            total += 1
            if history[i][1] == 'C':
                c += 1
        return c / total

    r_all = coop_rate(0)
    r5 = coop_rate(n - min(5, n))
    r10 = coop_rate(n - min(10, n))
    r20 = coop_rate(n - min(20, n))

    my_score = 0
    opp_score = 0
    for a, b in history:
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            opp_score += 1
    score_diff = my_score - opp_score

    def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            def_streak += 1
        else:
            break

    coop_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            coop_streak += 1
        else:
            break

    mutual_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            mutual_streak += 1
        else:
            break

    my_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_def_streak += 1
        else:
            break

    recent_dd = 0
    start = max(0, n - 15)
    for i in range(start, n):
        if history[i][0] == 'D' and history[i][1] == 'D':
            recent_dd += 1

    d_to_c = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D' and history[i][1] == 'C':
            d_to_c += 1

    if r_all <= 0.01:
        return 'D'

    if rounds_left == 1:
        return 'D'

    if last_opp == 'D':
        if last_me == 'C':
            return 'D'

        if mutual_streak >= 5:
            if r10 >= 0.55 and rng.random() < 0.45:
                return 'C'
            if rng.random() < 0.08:
                return 'C'
            return 'D'

        if mutual_streak >= 3:
            if r10 >= 0.6:
                return 'C'
            if r10 >= 0.35 and d_to_c > 0 and rng.random() < 0.35:
                return 'C'
            return 'D'

        if r10 >= 0.7:
            return 'C'

        if r10 >= 0.5:
            if d_to_c > 0 or mutual_streak == 1:
                if rng.random() < 0.55:
                    return 'C'
            elif rng.random() < 0.2:
                return 'C'
            return 'D'

        if r_all >= 0.6 and rng.random() < 0.25:
            return 'C'

        return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            if r5 <= 0.08 and rounds_left > 35 and d_to_c <= 1:
                if rng.random() < 0.75:
                    return 'C'
            return 'D'

        if rounds_left <= 2:
            if r5 >= 0.35 or r_all >= 0.6:
                return 'D'
            return 'C'

        if rounds_left <= 6:
            if r10 >= 0.85 and recent_dd == 0 and my_def_streak == 0:
                if rng.random() < 0.08:
                    return 'D'
                return 'C'

        if score_diff < -15 and r10 >= 0.75 and recent_dd == 0:
            if rng.random() < 0.2:
                return 'D'

        return 'C'

    return 'C'
